function scriptReply(w,choice,m){
 const p=personaScripts[w.id];
 if(!p)return null;
 if(m.guard>=60)return p.cold;
 const turn=state.stage[w.id]?.talk||0;
 // ほのかさんは直前の話題に対して答える。話題を飛ばしたり同じ説明を繰り返さない。
 if(w.id===7){
  if(/候補日|誘う/.test(choice))return p.invite;
  if(/通話/.test(choice))return p.call;
  if(/食べ物|お店/.test(choice))return p.food;
  if(/エリア/.test(choice))return p.area;
  if(/深掘り/.test(choice))return '最近はピンクや白を組み合わせることが多いです！小さなリボンのモチーフも作ってみたいなと思っています。';
  if(/共感/.test(choice))return 'そうなんです！友達が喜んでくれたので、作ってよかったなって思いました☺️ 次は自分用にも作ろうかなと思っています。';
  if(/経験も|自分の話|自分の好み/.test(choice))return '作る工程が好きなんですね！細かいパーツを組み合わせて形になっていくのって楽しいですよね。';
  if(/相手の休日や趣味|日常|ペース|休日/.test(choice))return '休日は友達とカフェに行くことも多いですし、家でアクセサリーを作ることもあります！ディズニーに行くのも好きです。';
  if(/プロフィールの共通点|短く挨拶|具体的に褒め/.test(choice))return p.open;
  return turn>3?p.food:p.hobby;
 }
 let key=/候補日|誘う/.test(choice)?'invite':/通話/.test(choice)?'call':/食べ物|お店/.test(choice)?'food':/エリア/.test(choice)?'area':/深掘り/.test(choice)?'depth':/共感/.test(choice)?'hobby':/経験も|自分の話|自分の好み/.test(choice)?'day':/プロフィールの共通点|短く挨拶|具体的に褒め/.test(choice)?'open':/日常|ペース|休日/.test(choice)?'day':/テンポ|趣味/.test(choice)?'hobby':'open';
 if(key==='open'&&turn>1)key='hobby';
 if(key==='hobby'&&turn>3)key='food';
 return p[key]||p.open;
}


const stageNames=['プロフィール理解','初回メッセージ','会話を継続','通話','初回デート'];
const depthNames=['表面層','中間層','深層'];

/* Core UI helpers */
const photoFiles={1:'character-photos/normalgirl.png',2:'character-photos/normalgirl.png',3:'character-photos/jiraikeigirl.png',4:'character-photos/shortcutgirl.png',5:'character-photos/olgirl.png',6:'character-photos/jiraikeigirl.png',7:'character-photos/normalgirl.png',8:'character-photos/olgirl.png'};
function photo(w){return w.photoUrl||photoFiles[w.id]||w.photoData||img(w.photo)}
function common(w){return w.topics.filter(t=>state.selectedTopics.includes(t))}
function compatibility(w){const ageGap=Math.abs(Number(state.user.age||27)-w.age),shared=common(w).length,agePenalty=ageGap<=4?0:ageGap<=6?8:ageGap<=8?18:30,scheduleFit=state.user.schedule===w.schedule?8:-14,artFit=(state.user.artTags||[]).some(t=>(w.artTags||[]).includes(t))?10:0,backgroundFit=state.user.background&&state.user.background!=='特になし'&&w.artLevel>=2?6:0,jobText=String(state.user.job||''),jobFit=/デザイナー|印刷|イベント/.test(jobText)&&w.artLevel>=2?8:/会社員|事務|企画/.test(jobText)&&/Webデザイナー|企画職|ITエンジニア|マーケター/.test(w.job)?5:0;return {ageGap,shared,agePenalty,scheduleFit,artFit,backgroundFit,jobFit,score:Math.max(10,Math.min(98,w.base+shared*4-agePenalty+scheduleFit+artFit+backgroundFit+jobFit)),hard:ageGap>=9&&shared<=1}}function score(w){return compatibility(w).score}function fitNote(w){const c=compatibility(w),n=[];if(c.ageGap>=7)n.push('年齢差が大きく、共通の趣味が少ないと会話の接点を作りにくい');if(c.scheduleFit<0)n.push('休日のタイプが異なり、会う日程を合わせにくい');if(c.artFit>0)n.push('美術・デザイン系の興味が共通している');return n.length?n.join('。')+'。':'年齢・趣味・休日の相性は比較的合わせやすい設定です。'}
function head(kicker,title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}
function toast(message){const el=$('#toast');if(!el)return;el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}
function progress(w){let s=state.stage[w.id]||{},v=[25,Math.min(100,(s.talk||0)*20),Math.min(100,(s.talk||0)*20),s.call?100:0,s.date?100:0];return v}
function pct(w){let p=progress(w);return Math.round(p.reduce((a,b)=>a+b,0)/p.length)}
function home(){return head('DISCOVER / MATCH','お相手を探す','19〜34歳の相手を表示。年齢差・共通の趣味・仕事の休日によって会話のしやすさが変わります。')+`<div class="grid-profiles">${women.map(w=>`<article class="profile-card" data-profile="${w.id}"><div class="profile-cover"><img src="${photo(w)}"><span class="online">オンライン</span></div><div class="profile-body"><div class="profile-title"><h3>${w.name} <span class="age">${w.age}歳</span></h3></div><div class="location">${w.area} ・ ${w.job} ・ ${w.schedule}</div><p class="bio">${w.bio}</p><div class="tags">${common(w).slice(0,3).map(t=>`<span class="tag common">${t}</span>`).join('')}</div><div class="card-actions"><button class="btn btn-primary" data-startchat="${w.id}">トークする</button><button class="btn btn-outline heart-btn" data-like="${w.id}">♡</button></div></div></article>`).join('')}</div>`}
function interests(){return head('YOUR INTERESTS','好み・共通点','興味のあるタグを選ぶと、相手との共通点に反映されます。')+`<section class="section-card"><div class="interest-grid">${topics.map(t=>`<button class="interest-option ${state.selectedTopics.includes(t)?'on':''}" data-topic="${t}">${t}</button>`).join('')}</div></section>`}
function talks(){return head('MESSAGES','トーク','マッチングした相手との会話を続けましょう。')+`<section class="section-card">${state.matched.length?state.matched.map(id=>{let w=women.find(x=>x.id===id),last=(state.chats[id]||[]).at(-1);return `<div class="talk-row" data-chat="${id}"><img src="${photo(w)}"><div><strong>${w.name}</strong><p>${last?escapeHtml(last.text):'マッチングしました。会話を始めましょう。'}</p></div></div>`}).join(''):'<p class="section-note">まだトークはありません。プロフィールから会話を始めてみましょう。</p>'}</section>`}
function likes(){return head('LIKES','いいね','気になる相手との会話を始めましょう。')+`<section class="section-card">${state.liked.length?state.liked.map(id=>{let w=women.find(x=>x.id===id);return `<div class="talk-row" data-chat="${id}"><img src="${photo(w)}"><div><strong>${w.name}</strong><p>${w.personality}</p></div></div>`}).join(''):'<p class="section-note">まだいいねはありません。</p>'}</section>`}
function mypage(){let f=funnelStats();return head('MY PAGE','マイページ','プロフィール・進捗・恋活ガイド。',`<button class="btn btn-outline" id="editUser">プロフィール編集</button>`)+`<section class="section-card"><h3>${escapeHtml(state.user.name)} ・ ${state.user.age}歳</h3><p class="section-note">${escapeHtml(state.user.area)} ／ ${escapeHtml(state.user.job)}</p><p>マッチング：${state.matched.length}人</p><p>デート成立：${Object.values(state.stage).filter(x=>x.date).length}件</p></section><section class="section-card"><h3 class="section-title">会話・デートの進捗（シミュレーション累計）</h3><p class="section-note">実際のアプリ活動実績ではなく、このシミュレーター内の進行状況です。</p><div class="depth-guide"><div><b>マッチ</b><p>${f.matched}人</p></div><div><b>初回返信あり</b><p>${f.firstReply}人</p></div><div><b>3往復以上</b><p>${f.threeExchanges}人</p></div><div><b>デート打診</b><p>${f.invite}人</p></div><div><b>通話クリア</b><p>${f.call}人</p></div><div><b>デート成立</b><p>${f.date}人</p></div></div><p class="section-note">お断り・終了：${f.closed}人。段階ごとの人数を分け、どこで止まっているか確認できます。</p></section><section class="section-card"><h3 class="section-title">恋活ガイド・参考資料</h3><p class="section-note">共有された動画文字起こしと、2026年11月の活動記録をもとに会話設計を改善しています。</p><div class="depth-guide guide-menu"><button class="guide-link" data-page="library"><span class="guide-symbol">▶</span><span><b>参考動画・文字起こしの要点</b><small>元動画リンクと学んだポイントを確認</small></span><span>›</span></button><button class="guide-link" data-page="profileGuide"><span class="guide-symbol">▤</span><span><b>マッチングアプリのプロフィール指南書</b><small>メイン写真・サブ写真・自己紹介文</small></span><span>›</span></button><button class="guide-link" data-page="conversationGuide"><span class="guide-symbol">☏</span><span><b>メッセージからデートまでの流れ</b><small>初回メッセージ・情報収集・誘い方</small></span><span>›</span></button><button class="guide-link" data-page="depthGuide"><span class="guide-symbol">◇</span><span><b>会話の深め方・踏み込み方</b><small>表面層・中間層・深層の使い分け</small></span><span>›</span></button></div></section>`}

function guideBack(){return `<button class="btn btn-outline" data-page="mypage">← マイページに戻る</button>`;}
function profileGuide(){return head('PROFILE GUIDE','プロフィール作成の指南書','文字起こしのプロフィール攻略パートを、実際に見直せるチェック項目に整理。',guideBack())+`<section class="section-card"><h3 class="section-title">プロフィール全体の考え方</h3><p>プロフィールは、写真・自己紹介文・好みカードが一貫して「どんな人か」「一緒に過ごすとどんな時間になりそうか」を伝える構成にします。自分の情報を並べるだけでなく、相手が会うイメージを持てる材料を用意します。</p><div class="tip">写真も文章も、最終的には「いいねを押す理由」と「初デートに行くイメージ」につながるかで見直す。</div></section><section class="section-card"><h3 class="section-title">1. メイン写真</h3><ul class="section-note"><li>明るく、表情が分かりやすい写真を選ぶ</li><li>暗い写真・顔が近すぎる／遠すぎる写真・自撮り感が強い写真は避ける</li><li>集合写真の切り抜きは避け、本人がすぐ分かるものにする</li><li>服装や髪型も含めて、清潔感と自分らしい雰囲気を伝える</li><li>背伸びしすぎず、実際に会ったときの印象と大きくずれない写真にする</li></ul></section><section class="section-card"><h3 class="section-title">2. サブ写真は役割を持たせる</h3><p>文字起こしでは5〜9枚を目安に、メイン写真を補強する構成が紹介されています。枚数だけを埋めるのではなく、写真ごとに役割を持たせます。</p><div class="depth-guide"><div><b>全身・服装</b><p>スタイルやファッション、全体の雰囲気が伝わる写真。</p></div><div><b>食べ物・飲み物・お店</b><p>好きなものや、一緒に出かける場面を想像しやすい写真。</p></div><div><b>趣味・休日の様子</b><p>自分の生活や興味が伝わり、会話のきっかけになる写真。</p></div><div><b>人柄が伝わる1枚</b><p>友人との時間や活動など、自然な人柄が分かる写真。写る人の許可とプライバシーに配慮。</p></div></div></section><section class="section-card"><h3 class="section-title">3. 自己紹介文</h3><p>文字起こしでは300文字以上、実例として400〜500文字程度が紹介されていました。構成は次の順番が参考になります。</p><ol class="section-note"><li>簡単な挨拶</li><li>仕事（前向きに、どんなことをしているか）</li><li>趣味・好きなこと</li><li>休日の過ごし方</li><li>性格や大切にしていること</li><li>恋愛観・どんな関係を築きたいか</li><li>最後に、相手が話しかけやすい一言</li></ol><p class="section-note">勤務先・年収・肩書きなどを誇張せず、事実の範囲で具体的に。自分を大きく見せるより、会ったときに自然につながる内容にします。</p></section><section class="section-card"><h3 class="section-title">4. 好みカード・趣味タグ</h3><ul class="section-note"><li>自分が本当に好きなものを中心に登録する</li><li>食事・カフェ・休日の過ごし方など、初デートの話題につながるタグも入れる</li><li>相手に合わせるためだけに、興味のないタグを増やさない</li><li>共通点ができたらメッセージでは軽く触れ、詳しい話は会話の流れに合わせる</li></ul></section><section class="section-card"><h3 class="section-title">公開前チェック</h3><ul class="section-note"><li>メイン写真で顔と雰囲気が分かる</li><li>サブ写真で服装・趣味・休日のイメージを補えている</li><li>自己紹介文に仕事・趣味・休日・人柄が入っている</li><li>書いてあることが写真や実際の自分と矛盾していない</li><li>相手が最初のメッセージで触れられる話題がある</li></ul></section>`}

function conversationGuide(){return head('MESSAGE FLOW','会話の流れ・デートへの進め方','5本の文字起こしにあったメッセージ設計と、相手の反応を尊重する進め方。',guideBack())+`<section class="section-card"><h3 class="section-title">メッセージの役割</h3><p>文字起こしで繰り返されていた軸は、メッセージを延々と続けることではなく、相手を知り、会うかどうかをお互いに判断できる状態にすることです。返信の負担を増やさず、安心感を作りながら進めます。</p><div class="tip">4日目や5ラリーは誘う期限ではなく、会話を見直す目安。返信量・質問返し・話題の広がり・相手の会う意思を見て判断する。</div></section><section class="section-card"><h3 class="section-title">基本の5ステップ</h3><div class="depth-guide"><div><b>1. 初回メッセージ</b><p>名前を呼び、プロフィールの具体的な点に触れ、共通点や好印象を一言添える。定型文だけにせず、相手のプロフィールに合う内容にする。</p><p class="tip">例：「〇〇さん、はじめまして。写真のカフェの雰囲気いいですね。自分もカフェ巡りが好きなので、マッチできて嬉しいです！」</p></div><div><b>2. アイスブレイク</b><p>返事に短くリアクションし、自分の話も少し返す。質問を連続させず、相手が返しやすい一つの話題にする。</p></div><div><b>3. デート情報を自然に確認</b><p>食べ物・飲み物の好み、行きやすいエリアや駅、休日の都合など、会うために必要な情報を会話の中で確認する。</p></div><div><b>4. 具体的に提案</b><p>相手の好みと会話に出た情報をもとに、お店やエリア、候補日を具体的に提案する。相手が選びやすいように、必要なら候補を2つ程度出す。</p></div><div><b>5. 約束を確認</b><p>合意した日時・場所を確認する。会う前に不安がある相手には、希望を聞いたうえで短い通話を提案してもよい。</p></div></div></section><section class="section-card"><h3 class="section-title">初デート前の誘い方・連絡手段</h3><ul class="section-note"><li>誠実さと会話の楽しさが伝わるやり取りを重ねる。相手のプロフィールに沿った話題と、自然な自己開示を意識する</li><li>会話が温まり、相手も前向きな反応を見せている段階で、自分から具体的なデートを提案する</li><li>連絡先交換や会う前の通話は、不安を減らす選択肢として提案できる。断られたらアプリ内のやり取りを続けるか、相手の希望に合わせる</li><li>連絡先交換・通話をデート成立の必須条件にしない。相手が望まない場合は求めない</li></ul><p class="section-note">追加動画では、男性から誘うことや初デート前の連絡先交換・通話が紹介されています。このガイドでは一律のルールではなく、相手の反応に合わせる実践のヒントとして扱います。</p></section><section class="section-card"><h3 class="section-title">返信しやすい文章にする</h3><ul class="section-note"><li>一度に複数の質問をしない</li><li>長文や硬すぎる敬語を続けず、自然で読みやすい文量にする</li><li>相手の文量・テンション・返信ペースに合わせる</li><li>共通点は見つけても、最初から細部まで聞きすぎない</li><li>自分の話も添えて、質問だけのやり取りにしない</li><li>返信をわざと遅らせるなどの駆け引きはしない</li></ul></section><section class="section-card"><h3 class="section-title">誘い方の例</h3><p>「この前話してた韓国料理、気になります。よかったら今度一緒に行きませんか？来週なら水曜か土曜あたりはどうですか？」</p><p class="section-note">候補を出すのは相手が選びやすくするため。断りにくくする目的で二択に追い込まない。「難しければ大丈夫」と伝え、相手が断れる余地を残す。</p></section><section class="section-card"><h3 class="section-title">反応が薄い・断られたとき</h3><ul class="section-note"><li>日程が合わないと言われ、相手から別日や代案が出たら、その提案をもとに調整する</li><li>曖昧な返事や代案のない断りが続く場合は、追いかけず一度引く</li><li>「またタイミング合えば」と伝えて会話を閉じ、相手からの連絡を待つ</li><li>通話や連絡先交換は、相手も望んでいる場合だけ提案する</li></ul><p class="section-note">文字起こしには再提案や通話誘導のノウハウもありましたが、このサイトでは相手の意思を尊重し、断りを覆そうとする追撃は推奨しません。</p></section>`}

function depthGuide(){return head('CONVERSATION DEPTH','会話の深め方・踏み込み方','文字起こしにあった「表面層・中間層・深層」を、信頼関係と相手の反応に合わせて使い分けます。',guideBack())+`<section class="section-card"><h3 class="section-title">3つの会話レイヤー</h3><p>話題を深くすること自体が正解ではありません。相手が話したそうか、こちらも話せるか、会話の流れに無理がないかを見ながら進めます。</p><div class="depth-guide"><div><b>01 表面層｜まずは話しやすい話題</b><p>趣味・食べ物・休日・旅行・最近の出来事・好きなお店など。初期の会話や、まだ距離がある相手との接点づくりに使います。</p><p class="section-note">例：「最近行ってよかったカフェありますか？」</p></div><div><b>02 中間層｜理由や価値観に少し触れる</b><p>仕事のやりがい・趣味を始めたきっかけ・理想の休日・大切にしていることなど。相手が自分の話を広げてくれたときに、一段だけ深めます。</p><p class="section-note">例：「写真を撮るの好きなんですね。始めたきっかけって何かあったんですか？」</p></div><div><b>03 深層｜大切な価値観や個人的な話</b><p>恋愛観・将来像・家族観・悩み・本音など。信頼関係ができ、相手自身が話したい様子のときに扱う話題です。</p><p class="section-note">例：「無理のない関係って、〇〇さんにとってどんな感じですか？」</p></div></div></section><section class="section-card"><h3 class="section-title">踏み込むタイミングの見方</h3><ul class="section-note"><li>相手から具体的なエピソードや感情が返ってくる</li><li>相手からも質問が返り、会話が一方通行になっていない</li><li>相手が話題を広げたり、関連する話を自分から足してくれる</li><li>こちらも同じくらい自己開示できる話題である</li></ul><p>反対に、短い返事が続く・話題を変えられる・質問に答えるだけになっている場合は、深追いせず表面層に戻します。</p></section><section class="section-card"><h3 class="section-title">深掘りの基本は「一段だけ」</h3><p>質問を重ねるより、相手の言葉を受け止めて、自分の似た経験や感想を少し返します。</p><div class="tip">相手：「休日は美術館に行くことが多いです」<br>返し方：「いいですね。展示空間を見るのも楽しいですよね。最近印象に残った展示ありますか？」</div><p class="section-note">相手が答えたくない話題は聞かない。恋愛観・家族・悩みなど個人的な話は、初期のメッセージで無理に聞き出さない。</p></section><section class="section-card"><h3 class="section-title">デート前とデート中で役割を分ける</h3><p>文字起こしでは、共通趣味の細かな深掘りはメッセージで長く続けず、会ってからの会話に回す考え方が紹介されていました。メッセージでは会うための共通点や好みを確認し、実際に会ったら相手の話したい方向に合わせて深めていきます。</p></section>`}




function moodState(id){state.mood??={};return state.mood[id]??(state.mood[id]={affection:35,safety:42,interest:48,guard:18,datingIntent:15,hidden:'まだ様子を見ている'})}
function moodView(id){let m=moodState(id);return `<button class="mood-heart" id="moodOpen" aria-label="相手の内面状態を確認"><span class="mood-heart-shape" style="background:linear-gradient(to top,#e86b91 0%,#e86b91 ${m.affection}%,#f4c5d3 ${m.affection}%,#f4c5d3 100%);-webkit-background-clip:text;background-clip:text;color:transparent">♥</span><b>${m.affection}</b></button>`;}
function moodModal(id){let m=moodState(id),w=women.find(x=>x.id===id);openModal(`<div class="modal-head"><h2>${w.name}さんの内面状態</h2><button class="close" data-close>×</button></div><p class="section-note">メッセージの文面とは別に管理している、シミュレーション上の内面パラメータです。</p><div class="mood-detail-heart"><span>♥</span><b>${m.affection}%</b><small>好意・親近感</small></div>${[['安心感',m.safety],['会話意欲',m.interest],['会う意思',m.datingIntent??15],['警戒度',m.guard]].map(([n,v])=>`<div class="metric-row"><span>${n}</span><strong>${v}%</strong></div><div class="progress-wrap"><div class="progress-fill" style="width:${v}%;${n==='警戒度'?'background:linear-gradient(90deg,#e7b36a,#df7186)':''}"></div></div>`).join('')}<div class="tip">内面メモ：${m.hidden}</div><p class="section-note">この表示はプレイヤー向けのゲーム情報です。相手のメッセージに状態がそのまま表れるとは限りません。</p>`)}
function choiceOptionsBase(w,id){
 const m=moodState(id),st=state.stage[id]||{},talk=st.talk||0;
 if(st.closed)return [];
 if(m.guard>=55)return ['相手の短い返答を受け止めて軽い話題に戻す','返信が短い理由を問い詰める','少し時間を置いて相手のペースに合わせる','会話を無理に続けるため質問を重ねる'].map((x,i)=>({text:x,index:i}));
 if(talk===0)return ['プロフィールの共通点に触れ、短く挨拶する','写真や雰囲気を具体的に褒める','初回から仕事や休日の詳細を聞く','長文で自分のことを詳しく説明する'].map((x,i)=>({text:x,index:i}));
 if(talk===1)return ['相手の話に共感し、自分の経験も少し話す','興味を持った点を一つだけ深掘りする','相手の返信内容に関係なく別の質問を重ねる','すぐに食事の約束を迫る'].map((x,i)=>({text:x,index:i}));
 if(talk===2)return ['自分の好みや休日の過ごし方も共有する','相手の休日や趣味を一つ聞く','食べ物や行ってみたいお店の好みを聞く','仕事や恋愛観をいくつも質問する'].map((x,i)=>({text:x,index:i}));
 const analysis=conversationAnalysis(id);
 if(!analysis.hasFood||!analysis.hasArea){
  const opts=[];
  if(!analysis.hasFood)opts.push('食べ物や行ってみたいお店の好みを聞く');
  if(!analysis.hasArea)opts.push('行きやすいエリアを聞く');
  opts.push('自分の好みや休日の過ごし方も共有する','興味を持った点を一つだけ深掘りする');
  return opts.slice(0,4).map((x,i)=>({text:x,index:i}));
 }
 if(talk>=4)return ['具体的な候補日を添えて食事に誘う','相手の都合を尊重して短い通話を提案する','お店や場所の希望を一つ確認する','相手の返答を待ってから日程を調整する'].map((x,i)=>({text:x,index:i}));
 return ['相手の都合を尊重して短い通話を提案する','自分の好みや休日の過ごし方も共有する','食べ物や行ってみたいお店の好みを聞く','行きやすいエリアを聞く'].map((x,i)=>({text:x,index:i}));
}

function choiceOptions(w,id){
 const list=choiceOptionsBase(w,id).slice(),turn=state.stage[id]?.talk||0;
 // 同じ画面の描画とクリック処理で順番が変わらない、ターンごとの疑似シャッフル
 let seed=(Number(id)*7919+turn*104729+list.length*37)>>>0;
 for(let i=list.length-1;i>0;i--){seed=(seed*1664525+1013904223)>>>0;const j=seed%(i+1);[list[i],list[j]]=[list[j],list[i]];}
 return list;
}

function chooseMessage(id,index){let w=women.find(x=>x.id===id),m=moodState(id),st=state.stage[id]||(state.stage[id]={matched:true,talk:0,call:false,date:false}),chosen=choiceOptions(w,id)[index];if(!chosen||st.closed)return;let fitData=compatibility(w),text=chosen.text,positive=/共通点|短く挨拶|具体的に褒め|共感|経験も|深掘り|日常|安心感|テンポよく|趣味|好み|エリア|通話|候補日/.test(text),pushy=/問い詰め|迫る|連続|重ねる|長文|急かす|踏み込んだ|質問だけ|反応を待たず|いきなり休日|詳細を聞く|いくつも質問/.test(text),fit=0;if(w.style==='慎重型'||w.style==='安心感重視')fit=/ペース|日常|安心感|短く|共感/.test(text)?1:0;if(w.style==='テンポ型'||w.style==='行動派')fit=/テンポ|趣味|具体的/.test(text)?1:0;if(w.style==='共感型'||w.style==='リアクション型')fit=/共感|リアクション|経験/.test(text)?1:0;if(w.style==='深掘り型')fit=/深掘り|経験|共感/.test(text)?1:0;if(positive){m.safety+=3+fit*3;m.interest+=3+fit*4;m.affection+=2+fit*2;m.datingIntent=Math.min(100,(m.datingIntent??15)+(/共感|経験も|好み|エリア/.test(text)?3:1));m.guard=Math.max(0,m.guard-2);}const scenario=personaScripts[w.id];if(scenario){const tailored=scenario.ideal.test(text);const inSequence=(st.talk===0&&/プロフィールの共通点|短く挨拶/.test(text))||(st.talk===1&&/共感|深掘り/.test(text))||(st.talk===2&&/自分の好み|休日や趣味|食べ物|お店/.test(text))||(st.talk===3&&/食べ物|お店|エリア/.test(text))||(st.talk>=4&&/候補日|通話/.test(text));const change=pushy?-18:inSequence?13+(tailored?3:0):tailored?5:-4;st.scriptScore=Math.max(-70,Math.min(100,(st.scriptScore||0)+change));st.scriptTurns=(st.scriptTurns||0)+1;}if(fitData.hard){m.interest-=9;m.safety-=5;m.guard+=8;}else if(fitData.ageGap>=7&&fitData.shared<=1){m.interest-=5;m.guard+=4;}if(fitData.scheduleFit<0&&/候補日|通話/.test(text)){m.interest-=4;m.guard+=3;}if(pushy){m.safety-=8;m.interest-=7;m.datingIntent=Math.max(0,(m.datingIntent??15)-8);m.guard+=14;m.affection-=4;}if(/踏み込んだ質問/.test(text)){m.guard+=16;m.safety-=10;}for(const k of ['safety','interest','affection','guard','datingIntent'])m[k]=Math.max(0,Math.min(100,m[k]));let outgoing=choiceToText(text,w);state.chats[id]??=[];state.chats[id].push({from:'me',text:outgoing});st.talk=Math.min(8,(st.talk||0)+1);let d=state.depth[id]||(state.depth[id]={surface:0,middle:0,deep:0,risk:0}),layer=classifyDepth(outgoing);if(layer==='surface')d.surface++;if(layer==='middle'){if(st.talk>=2)d.middle++;else d.risk++;}if(layer==='deep'){if(st.talk>=5&&m.safety>=65)d.deep++;else d.risk++;}if(/候補日を添えて/.test(text)){let accepted=m.guard<=35&&m.safety>=62&&m.interest>=58&&m.affection>=55&&(m.datingIntent??15)>=48;st.inviteAttempted=true;st.inviteCount=(st.inviteCount||0)+1;if(accepted){st.date=true;m.interest=Math.min(100,m.interest+8);m.affection=Math.min(100,m.affection+6);m.hidden='会ってみたい気持ちがあり、日程を調整したい';state.chats[id].push({from:'them',text:personaScripts[w.id]?.invite||'いいですね！予定を調整しますね。候補日を確認してみます。'});}else{st.closed=true;st.closeReason='date_declined';m.hidden='丁寧に返信しているが、今回は会う意思がない。予定を理由に間接的に断っている';m.interest=Math.max(0,m.interest-20);m.guard=Math.min(100,m.guard+18);state.chats[id].push({from:'them',text:'今月は予定がいっぱい詰まっちゃってて、ごめんなさい。'});}}else{let response=replyToChoice(w,text,m);if(m.guard>=60){m.hidden='表面上は丁寧に返信しているが、内心では距離を置きたい。返信頻度を下げたい状態。';}else if(m.interest<35){response='そうなんですね。今ちょっと忙しいので、また落ち着いたらお話ししましょう。';}state.chats[id].push({from:'them',text:response});}renderChat(id);}
function choiceToText(t,w){
 const p=personaUserLines[w.id]||{};
 if(/プロフィールの共通点/.test(t))return personaOpeners[w.id]||('マッチングありがとうございます！プロフィールの'+(common(w)[0]||'趣味')+'が気になりました。よろしくお願いします。');
 if(/雰囲気を具体的に褒め/.test(t))return p.compliment||'写真の雰囲気が素敵ですね。';
 if(/短い返答を受け止め|相手のペース/.test(t))return '返信ありがとうございます。無理のないペースで大丈夫なので、落ち着いたらまたお話ししましょう。';
 if(/少し時間を置いて/.test(t))return 'お仕事など忙しいと思うので、返信は落ち着いたときで大丈夫です。また話せそうなときにお話ししましょう。';
 if(/返信が短い理由を問い詰め/.test(t))return '返信が短めですが、何かありましたか？';
 if(/質問を重ねる|別の質問を重ねる|いくつも質問/.test(t))return 'ちなみに、ほかにはどんなことが好きですか？';
 if(/食事の約束を迫る/.test(t))return 'よかったら明日会いませんか？';
 if(/仕事や休日の詳細/.test(t))return 'お仕事は何時までですか？休みはいつですか？普段どこに行きますか？';
 if(/長文で自分のこと/.test(t))return '自分の趣味や仕事、休日の過ごし方をまとめて話しますね。';
 if(/共感/.test(t))return p.empathy||'それいいですね。自分も少し似た経験があります。';
 if(/深掘り/.test(t))return p.deepen||'それを好きになったきっかけを一つ聞いてもいいですか？';
 if(/自分の好み|自分の話/.test(t))return p.self||'自分も休日はゆっくり過ごすことが多いです。';
 if(/相手の休日や趣味|日常|ペース/.test(t))return p.day||'休日はどんなふうに過ごすことが多いですか？';
 if(/食べ物|お店/.test(t))return p.foodAsk||'好きな食べ物や最近行ってよかったお店はありますか？';
 if(/エリア|場所の希望/.test(t))return p.areaAsk||'普段ご飯に行くならどのあたりが行きやすいですか？';
 if(/通話/.test(t))return p.callAsk||'よかったら今度10〜15分くらい通話してみませんか？';
 if(/候補日|食事に誘う/.test(t))return p.inviteText||'よかったら来週あたりにご飯に行きませんか？都合のいい日を相談したいです。';
 if(/相手の返答を待って/.test(t))return '急がず、都合が分かったら教えてください。こちらも予定を合わせます。';
 return t+'。';
}
function replyToChoice(w,choice,m){return scriptReply(w,choice,m)||'そうなんですね！もう少し聞いてみたいです。'}

function depthStats(id){let d=state.depth[id]||{surface:0,middle:0,deep:0,risk:0};return {surface:Math.min(100,d.surface*25),middle:Math.min(100,d.middle*25),deep:Math.min(100,d.deep*25),risk:d.risk||0};}
function classifyDepth(text){const t=String(text||'').replace(/\s/g,'');if(/過去の恋愛|元恋人|元彼|元カノ|結婚観|結婚したい|将来どう|家族|家庭環境|トラウマ|弱み|本音|人生観|不安|悩み|つらかった|傷ついた|恋愛遍歴/.test(t))return 'deep';if(/価値観|大切にしている|仕事のやりがい|仕事観|学生時代|友達|きっかけ|好きになった理由|こだわり|理想の|どんな人|趣味を始めた|休日の過ごし方|考え方/.test(t))return 'middle';return 'surface';}
function depthAdvice(id){let d=depthStats(id);if(d.risk)return '深い話題が少し早い可能性があります。いったん相手の返答を受け止め、答えやすい話題に戻しましょう。';if(d.surface<50)return 'まずはプロフィールの共通点や食べ物・休日など、相手が短く返しやすい話題から。質問を重ねず、自分の好みも一言添えましょう。';if(d.middle<50)return '共通点が見えたら、好きになったきっかけや普段の過ごし方を一段だけ深掘り。相手も質問や自己開示を返してくれるか確認しましょう。';if(d.deep<50)return '深い話題は必須ではありません。相手からも本音や価値観を話してくれる場合に限り、無理のない範囲で触れましょう。';return '話題の深さは十分です。深掘りを続けるより、相手の反応に合わせて会う・通話など次の段階へ進めるか考えましょう。'}
function depthResult(id){let d=depthStats(id);return `<div class="side-card"><h3>会話の深さ・踏み込み度</h3><p class="section-note">深い話題の数ではなく、信頼と相互の自己開示に合わせられているかを見ます。</p>${depthNames.map((n,i)=>{let v=[d.surface,d.middle,d.deep][i];return `<div class="metric-row"><span>${n}</span><strong>${v}%</strong></div><div class="progress-wrap"><div class="progress-fill" style="width:${v}%"></div></div>`}).join('')}<div class="tip">${depthAdvice(id)}</div>${d.risk?`<p class="section-note" style="color:#d66b83">踏み込み過多のサイン：${d.risk}回。相手の反応が薄いときは話題を戻しましょう。</p>`:''}</div>`;}
function conversationAnalysis(id){const msgs=state.chats[id]||[],mine=msgs.filter(m=>m.from==='me'),txt=mine.map(m=>m.text||''),all=txt.join(' '),count=mine.length,avg=count?txt.reduce((n,s)=>n+s.length,0)/count:0,questions=(all.match(/[?？]/g)||[]).length,hasFood=/ご飯|ごはん|食事|ランチ|ディナー|カフェ|スイーツ|肉|魚|寿司|焼肉|イタリアン|居酒屋|お酒|飲み/.test(all),hasArea=/どの辺|どのあたり|エリア|駅|沿線|場所|新宿|渋谷|横浜|池袋|吉祥寺|町田|府中|調布/.test(all),hasInvite=/会いませんか|会いましょう|行きませんか|行きましょう|ご一緒|デート|今度.*(行|食)/.test(all),hasConcrete=/明日|明後日|今週|来週|[月火水木金土日]曜|[0-9０-９]+日|ランチ|夜ご飯|お茶/.test(all),self=/僕は|自分は|私は|自分も|僕も|私も|実は/.test(all),empathy=/わかる|分かります|大変|お疲れ|いいですね|楽しそう|素敵ですね|たしかに/.test(all),deepEarly=mine.some((m,i)=>i<2&&classifyDepth(m.text)==='deep'),ease=Math.max(10,Math.min(100,82-(avg>100?Math.min(28,(avg-100)*.25):0)-(questions>count+1?12:0)-(avg>180?12:0)+(self?4:0))),comfort=Math.max(10,Math.min(100,58+(self?12:0)+(empathy?10:0)+(count>=2?6:0)-(deepEarly?24:0))),leadership=Math.max(10,Math.min(100,35+(hasFood?14:0)+(hasArea?14:0)+(hasInvite?22:0)+(hasConcrete?12:0)+(count>=2?5:0)));let next='';const last=msgs.at(-1);if(!count)next='最初の一通は、プロフィールの雰囲気やセンスを軽く褒め、共通点を一言添えて、会ってみたい意図を自然に伝えます。';else if(last?.from==='them'&&/忙し|予定|難し|その日は|無理/.test(last.text||''))next='断りを否定せず受け止め、別日を1〜2候補だけ出しましょう。理由を問い詰めず、相手の都合に合わせる姿勢も大切です。';else if(last?.from==='them'&&/もう少し|メッセージ|仲良く/.test(last.text||''))next='会うことを急かさず、短い通話を提案するか、相手が安心できる範囲で話す時間を作りましょう。';else if(hasInvite&&hasConcrete)next='誘いの方向性は伝わっています。相手の返答を待ち、OKなら日時・場所を具体化。曖昧なら選びやすい候補を2つに絞ります。';else if(!hasFood)next='共通点を細かく掘り下げすぎず、好きな食べ物や行ってみたい店を軽く聞いて、デートの話題につなげましょう。';else if(!hasArea)next='食の好みが分かったら、普段出かけるエリアや行きやすい駅を一つ聞きましょう。';else if(!hasInvite)next='お店・食べ物とエリアが見えたら、雑談を引き延ばさず、具体的な提案に進めるタイミングです。';else next='相手の返答に合わせて日程を調整しましょう。予定が先になる場合は、必要に応じて通話で安心感を作ります。';const st=state.stage[id]||{},scriptFit=Math.max(0,Math.min(100,Math.round(55+(st.scriptScore||0))));return {count,avg:Math.round(avg),ease,comfort,leadership,scriptFit,hasFood,hasArea,hasInvite,hasConcrete,deepEarly,next};}
function adviceCard(id){const a=conversationAnalysis(id);return `<div class="side-card"><h3>次の一手・メッセージ診断</h3><p class="section-note">動画の考え方をもとに、返信のしやすさ・安心感・デートへの進め方を確認します。実際の成功率ではなく練習用の目安です。</p><div class="metric-row"><span>返信しやすさ</span><strong>${a.ease}/100</strong></div><div class="progress-wrap"><div class="progress-fill" style="width:${a.ease}%"></div></div><div class="metric-row"><span>安心感・相互性</span><strong>${a.comfort}/100</strong></div><div class="progress-wrap"><div class="progress-fill" style="width:${a.comfort}%"></div></div><div class="metric-row"><span>デートへの段取り</span><strong>${a.leadership}/100</strong></div><div class="progress-wrap"><div class="progress-fill" style="width:${a.leadership}%"></div></div><div class="metric-row"><span>相手別シナリオ適合度</span><strong>${a.scriptFit}/100</strong></div><div class="progress-wrap"><div class="progress-fill" style="width:${a.scriptFit}%"></div></div><div class="tip">${a.next}</div><p class="section-note">送信回数：${a.count}回 ／ 平均文字数：${a.avg}文字。目安は5ラリー前後ですが、相手の反応や安心感を優先します。</p></div>`;}
function library(){return head('REFERENCE / LEARNING','参考動画','共有された文字起こしの内容を、会話診断・採点・アドバイスに反映しています。',`<button class="btn btn-outline" id="addResource">＋ 動画を追加</button>`)+`<section class="section-card"><h3 class="section-title">今回の動画から反映した考え方</h3><div class="depth-guide"><div><b>01 返信しやすさ</b><p>短く要点を伝え、質問を重ねない。共通点は軽く触れ、細かく掘り下げすぎない。</p></div><div><b>02 安心感と相互性</b><p>砕けすぎない敬語、相手の温度感に合わせたリアクション、自分の話も返す自己開示。</p></div><div><b>03 デートへの段取り</b><p>食べ物・店の好みとエリアを自然に把握し、情報が揃ったら具体的に誘う。</p></div></div><p class="section-note">文字起こしの誤変換は前後の文脈で補って整理しています。動画内の主張をそのまま正解として固定せず、相手の意思・安心感・断る自由を優先する形に調整しています。</p></section><section class="section-card"><h3 class="section-title">初デートの約束につなげるポイント（追加動画）</h3><div class="depth-guide"><div><b>01 誠実で楽しいメッセージ</b><p>動画内の調査では、初デートを決めた理由として「メッセージが誠実そう」が35.6%、「メッセージが楽しかった」が20%と紹介。プロフィールの印象だけでなく、会話の安心感や楽しさを積み重ねる。</p></div><div><b>02 自分から自然に誘う</b><p>動画内では「男性から誘ってほしい」が90.1%と紹介。会話の流れや相手の反応を見て、行き先・内容を添えて具体的に提案する。</p></div><div><b>03 連絡先交換・通話は双方の希望で</b><p>初デート前にLINEなどへ移行する例や、会う前に通話した経験がある女性が57.8%という調査結果を紹介。連絡先交換や通話は安心材料になり得るが、必須条件ではなく、相手も希望する場合に提案する。</p></div></div><p class="section-note">上記の割合は動画の文字起こしにある紹介値です。調査対象・実施時期・設問の詳細は文字起こしから確認できません。性別やアプリ利用者全体に当てはまる絶対的なルールとして扱わず、相手の反応と意思を優先します。</p></section><section class="section-card"><h3 class="section-title">5ラリーを目安にした会話の流れ</h3><div class="depth-guide"><div><b>1. 初回メッセージ</b><p>挨拶・プロフィールへの具体的な一言・共通点・会う意図を自然に伝える。</p></div><div><b>2. アイスブレイク</b><p>相手の返答に合わせて短くリアクションし、食べ物や好きな店の話題へ。</p></div><div><b>3. 情報を集める</b><p>行きたい店や食の好み、普段出かけるエリア・駅を確認する。</p></div><div><b>4. 具体的に誘う</b><p>店・場所・日程の候補を出す。断られたら別日を一度提案する。</p></div><div><b>5. 約束を整える</b><p>予定を確認し、必要なら短い通話で安心感を作る。連絡先交換は双方が望む場合だけ。</p></div></div><p class="section-note">5ラリーは目安です。返信が遅い・短い・迷っている場合に、回数だけを理由に誘いを急がせることはしません。</p></section><section class="section-card"><h3 class="section-title">採点・アドバイスの仕組み</h3><ul class="section-note"><li>返信しやすさ：文章の長さ、質問の数、返答の負担を確認</li><li>安心感・相互性：自己開示、共感、相手の温度感への合わせ方を確認</li><li>デートへの段取り：食の好み、エリア、具体的な誘い・日程候補を確認</li><li>会話の深さ：表面層・中間層・深層を別軸で記録し、深掘りの早さも確認</li></ul><p class="section-note">現在はキーワードや文章量を使ったルールベースの練習用評価です。実際の人間の感情やマッチング成功率を正確に予測するものではありません。</p></section><section class="section-card"><h3 class="section-title">登録済みの参考動画（${state.resources.length}）</h3>${state.resources.map(r=>`<div class="resource-row"><div class="resource-icon">▶</div><div class="resource-content"><strong>${r.title}</strong><span>${r.category}</span><p>${r.memo}</p><a href="${r.url}" target="_blank" rel="noopener">YouTubeで動画を見る ↗</a></div></div>`).join('')}</section><section class="section-card"><h3 class="section-title">プロフィール写真の追加場所</h3><p class="section-note">今後追加する写真は、GitHubリポジトリ直下の <strong>character-photos/</strong> フォルダへアップロードしてください。</p><div class="tip">フォルダ：character-photos/<br>対応形式：PNG・JPG・WebP<br>おすすめの名前：profile-1-sakura.png のように、誰の写真か分かる半角英数字の名前</div><p class="section-note">写真を追加したら、このフォルダに画像を入れ、photo-map.jsonに人物名とファイル名を記録します。サイトへの割り当ては、写真名と対象プロフィールを指定すれば更新できます。</p><a class="btn btn-outline" href="https://github.com/ryofukazawa324-ai/matchappsimulate/tree/main/character-photos" target="_blank" rel="noopener">写真フォルダを開く ↗</a></section>`}

function render(){let view={home,interests,talks,mypage,likes,library,profileGuide,conversationGuide,depthGuide}[state.page]||home;$('#app').innerHTML=view();$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));}
function openModal(html){$('#modalRoot').innerHTML=`<div class="modal" role="dialog" aria-modal="true">${html}</div>`}
function closeModal(){$('#modalRoot').innerHTML=''}
function detail(id){let w=women.find(x=>x.id===id),c=common(w),fit=compatibility(w);openModal(`<div class="modal-head"><h2>プロフィール</h2><button class="close" data-close>×</button></div><div class="detail-hero"><img src="${photo(w)}"><div class="detail-info"><h2>${w.name} <span class="age">${w.age}歳</span></h2><div class="location">${w.area} ・ ${w.job} ・ ${w.height} ・ ${w.schedule}</div><p>${w.bio}</p><div class="tags">${w.topics.map(t=>`<span class="tag ${c.includes(t)?'common':''}">${t}</span>`).join('')}</div></div></div><div class="divider"></div><div class="metric-row"><span>共通する話題</span><strong>${c.length} 個</strong></div><div class="metric-row"><span>会話相性スコア（仮想）</span><strong style="color:#df6b8c">${score(w)}%</strong></div><p class="section-note">性格タイプ：${w.personality}<br>${w.history}<br>美術・デザイン：${w.background}<br>見た目：${w.appearance}</p><div class="tip">${fitNote(w)}</div><div class="tip">会話のきっかけ：${w.intro}</div><div style="display:flex;gap:8px;margin-top:17px"><button class="btn btn-primary" style="flex:1" data-like="${id}">♡ いいね！</button><button class="btn btn-outline" data-startchat="${id}">トークを始める</button></div>`)}
function like(id){if(!state.liked.includes(id))state.liked.push(id);state.stage[id]={...(state.stage[id]||{}),matched:true};if(!state.matched.includes(id))state.matched.push(id);state.chats[id]??=[];render();toast('マッチングしました！トークを始めましょう');}
function chat(id){state.current=id;state.page='talks';render();renderChat(id)}
function renderChat(id){let w=women.find(x=>x.id===id),msgs=state.chats[id]||[],p=progress(w),pc=pct(w),m=moodState(id),st=state.stage[id]||{},choices=choiceOptions(w,id),callReady=st.talk>=3&&m.guard<=65&&m.safety>=42&&m.interest>=40&&!st.call&&!st.closed;$('#app').innerHTML=head('MESSAGE / CONVERSATION',w.name+'さんとのトーク','相手の反応を見ながら、会話を選びましょう。',`<div class="chat-actions-top">${moodView(id)}<button class="btn btn-outline" id="callStart" ${callReady?'':'disabled'}>${st.call?'通話クリア済み':callReady?'通話フェーズへ ↗':'通話はもう少し安心感が必要'}</button></div>`)+`<div class="conversation-layout"><section class="chat-panel"><div class="chat-header"><img src="${photo(w)}"><div><strong>${w.name} <span class="age">${w.age}歳</span></strong><small>オンライン ・ ${w.personality}</small></div></div><div class="chat-body" id="chatBody">${msgs.length?msgs.map(m=>`<div class="bubble ${m.from==='me'?'me':'them'}">${escapeHtml(m.text)}<span class="time">${m.from==='me'?'送信済み':'既読'}</span></div>`).join(''):`<div class="bubble them">マッチングありがとうございます！よろしくお願いします☺️<span class="time">既読</span></div>`}${st.closed?'<div class="tip">この相手とのシミュレーションは終了しました。進捗をリセットすると最初からやり直せます。</div>':''}</div>${st.closed?'':`<div class="choice-area"><div class="choice-heading">次の返信を選んでください <span>相手ごとの会話台本に沿って反応・評価が変化</span></div><div class="choice-grid">${choices.map((c,i)=>`<button class="choice" data-messagechoice="${i}">${escapeHtml(choiceToText(c.text,w))}</button>`).join('')}</div></div>`}</section><aside><div class="side-card"><div class="side-card-title-row"><h3>会話の進捗</h3><button class="reset-progress" data-reset-progress="${id}">個別リセット</button></div><div class="result-score" style="font-size:32px">${pc}%</div><div class="progress-wrap"><div class="progress-fill" style="width:${pc}%"></div></div>${stageNames.map((n,i)=>`<div class="metric-row"><span>${n}</span><strong>${p[i]}%</strong></div>`).join('')}${st.call?'<p class="section-note">通話：クリア</p>':callReady?'<p class="section-note">通話：開始可能</p>':'<p class="section-note">通話：安心感・警戒心の条件を満たすと解放</p>'}</div><div class="side-card"><h3>会話アシスト</h3><p class="section-note">選択肢は相手の性格と内面状態に応じて変わります。</p>${suggestions(w).map(s=>`<div class="suggestion">${s}</div>`).join('')}</div>${depthResult(id)}${adviceCard(id)}<div class="side-card"><h3>相手別シナリオ</h3><strong>${personaScripts[w.id]?.label||w.style}</strong><p class="section-note">${personaGoals[w.id]||''}</p><p class="section-note">${({1:'カフェ・写真の話から共通点を作り、仕事の話は相手の興味に合わせて少しだけ。',2:'勤務の不規則さを理解し、返信頻度や日程を急かさず安心感を作る。',3:'音楽・服の話でテンポよく盛り上がり、好みの店やエリアへつなぐ。',4:'急に距離を詰めず、映画や読書の話を重ねて信頼を作る。',5:'旅行先や食の具体的な話から、店選びと日程調整へ自然に進む。',6:'ゲームやイラストの話を具体的に聞き、自分の趣味も少し共有する。',7:'ハンドメイドやカフェの話に共感し、明るいテンポで会話する。',8:'美術館・展示・デザインの視点を交換し、落ち着いた会話から誘う。'})[w.id]}</p><div class="tip">共通点：${common(w).join('、')||'まだありません'}<br>見た目：${w.appearance}</div></div></aside></div>`;$(' #callStart'.trim()).onclick=()=>{if(callReady)call(id);else toast('もう少しメッセージで安心感を作りましょう')};$('#chatBody').scrollTop=$('#chatBody').scrollHeight;$$('[data-messagechoice]').forEach(b=>b.onclick=()=>chooseMessage(id,Number(b.dataset.messagechoice)));$$('#moodOpen').forEach(b=>b.onclick=()=>moodModal(id));$$('[data-reset-progress]').forEach(b=>b.onclick=()=>resetProgressPrompt(id));}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function escapeAttr(s){return escapeHtml(s).replace(/"/g,'&quot;')}
function suggestions(w){let a=conversationAnalysis(w.id),c=common(w),pool=[];if(!a.count){pool.push('プロフィールの雰囲気が素敵だと思いました。共通点もあって嬉しいです！');pool.push('マッチングありがとうございます。仲良くなったらご飯でも行きましょう！');}else if(!a.hasFood){pool.push('好きな食べ物ってありますか？');pool.push('最近行ってよかったお店ありますか？');}else if(!a.hasArea){pool.push('普段ご飯に行くときはどの辺が多いですか？');pool.push('行きやすい駅やエリアってありますか？');}else if(!a.hasInvite){pool.push('そのお店気になります。今度一緒に行きませんか？');pool.push('よかったら今度ご飯行きましょう！');}else{pool.push('今週末か来週のどちらかで都合いい日はありますか？');pool.push('難しければ別の日でも大丈夫です！');}if(c.length)pool.push(`共通の「${c[0]}」も気になります。自分も好きです！`);pool.push('自分もそういうの好きです。');return [...new Set(pool)].slice(0,4);}
function sendMessage(id,text){let w=women.find(x=>x.id===id);state.depth[id]??={surface:0,middle:0,deep:0,risk:0};let layer=classifyDepth(text),d=state.depth[id],rapport=(state.stage[id]?.talk||0)+(state.stage[id]?.call?3:0);if(layer==='surface')d.surface++;if(layer==='middle'){if(rapport>=1)d.middle++;else d.risk++;}if(layer==='deep'){if(rapport>=4)d.deep++;else d.risk++;}state.chats[id]??=[];state.chats[id].push({from:'me',text});state.stage[id]??={matched:true,talk:0,call:false,date:false};state.stage[id].talk=Math.min(5,(state.stage[id].talk||0)+1);renderChat(id);setTimeout(()=>{state.chats[id].push({from:'them',text:reply(w,text)});renderChat(id);toast('返信が届きました')},600)}
function reply(w,text){let c=common(w),talk=state.stage[w.id]?.talk||1,hit=c.find(t=>text.includes(t));if(hit)return `わあ、${hit}好きなんですね！私も好きです☺️ ${hit==='旅行'?'最近はどこか行きましたか？':'どんなところが好きですか？'}`;if(/好き|趣味|休み|休日/.test(text))return `そうですね！色々ありますよ〜！ ${w.intro}`;if(/会う|デート|ごはん|ご飯|カフェ/.test(text))return talk>=3?'いいですね！もう少しお話しして、ぜひ行ってみたいです☺️':'お誘い嬉しいです！もう少しメッセージでお話しできたら嬉しいです。';if(talk>=4)return 'それ面白いですね！話していると楽しいです☺️ よかったら今度通話してみませんか？';return ['いいですね！それは初めて聞きました！','わかります、私もそういうの好きです☺️','そうなんですね！もう少し詳しく聞きたいです！','たしかに！ちなみに休日は何していることが多いですか？'][Math.floor(Math.random()*4)]}
function call(id){let w=women.find(x=>x.id===id),m=moodState(id),st=state.stage[id]||{};if(st.closed||!(st.talk>=3&&m.guard<=65&&m.safety>=42&&m.interest>=40)){toast('通話を始めるには、もう少し安心感が必要です');return;}state.callSessions??={};state.callSessions[id]={round:0,limit:6,good:0,bad:0};renderCall(id);}
function callChoices(w,id){
 let m=moodState(id),r=state.callSessions?.[id]?.round||0,p=personaScripts[w.id]||{};
 if(m.guard>=55)return ['相手の話を遮らず、まず最後まで聞く','自分の話を長く続ける','恋愛観や過去のことを細かく聞く','相手の反応を見て話題を軽く変える'];
 if(r<2)return [p.label+'に関係する趣味の話をもう少し聞く','最近あった小さな出来事を共有する','仕事やプライベートを細かく質問する','相手の話に相づちだけして終える'];
 if(r<4)return ['相手の考えを一つだけ聞き、自分の考えも話す','相手の話に共感して少し自己開示する','過去の恋愛や結婚観を聞く','沈黙が怖くて質問を続ける'];
 return ['一緒に行けそうな場所やお店の話を軽くする','会って話すのも楽しそうと自然に伝える','今すぐ会う日を決めようと迫る','相手がどう感じているかを確認する'];
}
function renderCall(id){let w=women.find(x=>x.id===id),c=state.callSessions[id],round=c.round,choices=callChoices(w,id);openModal(`<div class="modal-head"><h2>30分通話シミュレーション</h2><button class="close" data-close>×</button></div><div class="call-screen"><img src="${photo(w)}"><h2>${w.name}</h2><p>通話中 ・ 30分の想定</p><div class="call-timer">残りラリー：${c.limit-round} / 6</div><div class="progress-wrap"><div class="progress-fill" style="width:${round/c.limit*100}%"></div></div><p>相手の反応を見ながら、会話を選んでください。</p></div><div style="margin-top:16px"><p class="section-note">踏み込みすぎず、安心感と会話意欲を育てましょう。</p><div class="choice-grid">${choices.map((x,i)=>`<button class="choice" data-callchoice="${i}">${x}</button>`).join('')}</div></div>`);$$('[data-callchoice]').forEach(b=>b.onclick=()=>callChoice(id,Number(b.dataset.callchoice)));}function callChoice(id,index){let w=women.find(x=>x.id===id),m=moodState(id),st=state.stage[id],c=state.callSessions[id],choice=callChoices(w,id)[index];if(!c||!choice)return;let good=/聞く|共有|共感|自己開示|軽く|自然に|確認して|受け止め|ペース/.test(choice),dateTalk=/一緒に行けそう|会って話す|どう感じているか/.test(choice),bad=/細かく質問|過去の恋愛|質問を続ける|迫る|長く続ける/.test(choice);if(good){m.safety+=6;m.interest+=5;m.affection+=3;m.datingIntent=Math.min(100,(m.datingIntent??15)+(dateTalk?9:2));m.guard=Math.max(0,m.guard-6);c.good++;}if(bad){m.safety-=9;m.interest-=8;m.affection-=4;m.guard+=13;c.bad++;}for(const k of ['safety','interest','affection','guard'])m[k]=Math.max(0,Math.min(100,m[k]));c.round++;state.chats[id]??=[];const callScript=personaScripts[w.id],callLine=m.guard>=65?'そうなんですね。そろそろ時間も大丈夫ですか？':good?(c.round<=2?callScript?.hobby:c.round<=4?callScript?.depth:callScript?.food):'そうなんですね。';state.chats[id].push({from:'them',text:callLine||'それ、わかります。話しやすいですね。'});if(m.guard>=78||m.interest<=18){st.closed=true;st.closeReason='call_cutoff';m.hidden='通話中に距離を置きたいと感じ、会話を続ける気持ちがなくなった';finishCall(id,false,true);return;}if(c.round>=c.limit){let passed=m.safety>=58&&m.interest>=55&&m.guard<=42&&m.affection>=48&&c.good>=4&&c.bad<=1;if(passed){st.call=true;m.interest=Math.min(100,m.interest+8);m.affection=Math.min(100,m.affection+6);m.hidden='通話して安心感が増し、実際に会ってみたいと思っている';}else if(m.guard>=65||m.interest<30){st.closed=true;st.closeReason='call_cutoff';m.hidden='通話を通して相性が合わないと感じ、見切っている';}finishCall(id,passed,st.closed);return;}renderCall(id);}
function finishCall(id,passed,closed){let w=women.find(x=>x.id===id),m=moodState(id),c=state.callSessions[id];renderChat(id);openModal(`<div class="modal-head"><h2>通話結果</h2><button class="close" data-close>×</button></div><div style="text-align:center;padding:18px"><div class="result-score" style="font-size:28px">${passed?'通話クリア！':closed?'関係終了':'今回はクリアならず'}</div><p class="section-note">${passed?'会話のテンポと安心感が合い、実際に会ってみたいと思ってもらえました。':closed?'踏み込み方や会話の相性から、相手が関係を続けない判断をしました。':'もう少し安心感を作る必要がありました。メッセージで関係を整えましょう。'}</p><div class="tip">30分想定・${c.round}ラリー ／ 安心感 ${m.safety}% ／ 警戒度 ${m.guard}%</div>${passed?'<button class="btn btn-primary" style="margin-top:16px" data-nextdate="'+id+'">デートの日程を決める</button>':closed?'<p class="section-note">この相手とのやりとりは終了です。進捗を個別リセットすると再挑戦できます。</p>':'<button class="btn btn-outline" style="margin-top:16px" data-continuechat="'+id+'">メッセージに戻る</button>'}</div>`);}
function dateInvite(id){let w=women.find(x=>x.id===id),m=moodState(id),st=state.stage[id]||(state.stage[id]={matched:true,talk:0,call:false,date:false}),accepted=m.guard<=38&&m.safety>=58&&m.interest>=52&&m.affection>=48&&(m.datingIntent??15)>=48&&(st.call||st.talk>=4);if(accepted){st.date=true;m.hidden='実際に会ってみたいと思い、日程を調整したい';state.chats[id]??=[];state.chats[id].push({from:'them',text:personaScripts[id]?.invite||'いいですね！予定を調整しますね。候補日を確認してみます。'});openModal(`<div class="modal-head"><h2>日程調整へ</h2><button class="close" data-close>×</button></div><p>${w.name}さんから候補日が届きました。</p><div class="tip">会う約束が成立しました。候補日を確認して日程を決めましょう。</div><button class="btn btn-primary" style="margin-top:16px" data-finish="${id}">約束を確認する</button>`);}else{st.closed=true;st.closeReason='date_declined';m.hidden='今回は会う意思がなく、予定を理由に丁寧に断っている';state.chats[id]??=[];state.chats[id].push({from:'them',text:'今月は予定がいっぱい詰まっちゃってて、ごめんなさい。'});openModal(`<div class="modal-head"><h2>お誘いへの返答</h2><button class="close" data-close>×</button></div><p class="section-note">${w.name}さんから丁寧な返信がありました。</p><div class="tip">「今月は予定がいっぱい」という返答は、今回は会う意思がない間接的なお断りとして扱います。追いメッセージで挽回するルートはありません。</div><button class="btn btn-outline" style="margin-top:16px" data-continuechat="${id}">会話履歴を見る</button></div>`);}}
function resetProgressPrompt(id){let w=women.find(x=>x.id===id);openModal(`<div class="modal-head"><h2>会話の進捗をリセット</h2><button class="close" data-close>×</button></div><p>${w.name}さんとの会話履歴・好意・安心感・警戒度・通話結果・進捗を初期状態に戻します。</p><p class="section-note">この相手だけが対象です。他の相手の進捗には影響しません。</p><button class="btn btn-outline" data-close>キャンセル</button><button class="btn btn-primary" style="margin-left:8px" data-confirm-reset="${id}">リセットする</button>`);}
function resetProgress(id){delete state.stage[id];delete state.mood[id];delete state.chats[id];delete state.depth[id];delete state.callCount[id];if(state.callSessions)delete state.callSessions[id];state.stage[id]={matched:true,talk:0,call:false,date:false};state.mood[id]={affection:35,safety:42,interest:48,guard:18,datingIntent:15,hidden:'まだ様子を見ている'};closeModal();chat(id);toast('この相手の進捗をリセットしました');}
function addResource(){openModal(`<div class="modal-head"><h2>参考動画を追加</h2><button class="close" data-close>×</button></div><div class="field"><label>動画タイトル</label><input id="rTitle" placeholder="動画のタイトル"></div><div class="field"><label>YouTubeなどのURL</label><input id="rUrl" placeholder="https://youtu.be/..."></div><div class="field"><label>カテゴリ</label><input id="rCategory" placeholder="会話・プロフィール・デートなど"></div><div class="field"><label>内容メモ</label><input id="rMemo" placeholder="参考にしたいポイント"></div><button class="btn btn-primary" id="saveResource">追加する</button>`)}

function bindProfileSave(){
 const button=document.getElementById('saveUser');
 if(!button)return;
 button.onclick=()=>{
  const age=Number(document.getElementById('uAge')?.value);
  if(!Number.isFinite(age)||age<19||age>34){toast('年齢は19〜34歳で設定してください');return;}
  const value={...state.user,name:document.getElementById('uName')?.value.trim()||'Yuki',age,area:document.getElementById('uArea')?.value.trim()||'',job:document.getElementById('uJob')?.value.trim()||'',schedule:document.getElementById('uSchedule')?.value||'土日休み',background:document.getElementById('uBackground')?.value||'特になし',artTags:[...document.querySelectorAll('input[name="uArtTag"]:checked')].map(x=>x.value)};
  try{localStorage.setItem('matchlab_user',JSON.stringify(value));state.user=value;closeModal();render();toast('プロフィールを保存しました');}
  catch(error){console.error('プロフィール設定の保存に失敗しました',error);toast('保存できませんでした。ブラウザの保存領域を確認してください');}
 };
}

function userSettings(){openModal(`<div class="modal-head"><h2>あなたのプロフィール</h2><button class="close" data-close>×</button></div><div class="form-row"><div class="field"><label>ニックネーム</label><input id="uName" value="${escapeHtml(state.user.name)}"></div><div class="field"><label>年齢（19〜34歳）</label><input id="uAge" type="number" min="19" max="34" value="${state.user.age}"></div></div><div class="form-row"><div class="field"><label>居住地</label><input id="uArea" value="${escapeHtml(state.user.area)}"></div><div class="field"><label>職業</label><input id="uJob" value="${escapeHtml(state.user.job)}" placeholder="会社員・印刷系・イベントスタッフ・デザイナーなど"></div></div><div class="form-row"><div class="field"><label>休日のタイプ</label><select id="uSchedule"><option value="土日休み" ${state.user.schedule==='土日休み'?'selected':''}>土日休み</option><option value="シフト制" ${state.user.schedule==='シフト制'?'selected':''}>シフト制</option></select></div><div class="field"><label>美術・デザインとの関わり</label><select id="uBackground"><option value="特になし" ${state.user.background==='特になし'?'selected':''}>特になし</option><option value="美大生・美大出身" ${state.user.background==='美大生・美大出身'?'selected':''}>美大生・美大出身</option><option value="服飾専門学生・出身" ${state.user.background==='服飾専門学生・出身'?'selected':''}>服飾専門学生・出身</option><option value="美術に少し興味あり" ${state.user.background==='美術に少し興味あり'?'selected':''}>美術に少し興味あり</option></select></div></div><div class="field"><label>趣味タグ（複数選択可）</label><div class="interest-grid">${['アート・デザイン','絵を描く','ハンドメイド','美術館','ファッション'].map(t=>`<label class="tag"><input type="checkbox" name="uArtTag" value="${t}" ${(state.user.artTags||[]).includes(t)?'checked':''}> ${t}</label>`).join('')}</div></div><button class="btn btn-primary" id="saveUser">保存する</button>`)
bindProfileSave();}
document.addEventListener('click',e=>{let t=e.target.closest('button,[data-profile],[data-chat]');if(!t)return;if(t.dataset.page){state.page=t.dataset.page;render()}if(t.dataset.profile)detail(Number(t.dataset.profile));if(t.dataset.detail)detail(Number(t.dataset.detail));if(t.dataset.like)like(Number(t.dataset.like));if(t.dataset.filter){state.filter=t.dataset.filter;render()}if(t.dataset.topic){let x=t.dataset.topic;state.selectedTopics=state.selectedTopics.includes(x)?state.selectedTopics.filter(a=>a!==x):[...state.selectedTopics,x];render()}if(t.dataset.chat)chat(Number(t.dataset.chat));if(t.dataset.suggest)toast('会話の選択肢から返信を選んでください');if(t.dataset.startchat){let id=Number(t.dataset.startchat);closeModal();if(!state.matched.includes(id))state.matched.push(id);state.stage[id]??={matched:true,talk:0};chat(id)}if(t.id==='editInterests'){state.page='interests';render()}if(t.id==='addResource')addResource();if(t.id==='saveResource'){let title=$('#rTitle').value.trim(),url=$('#rUrl').value.trim();if(!title||!(url.startsWith('https://')||url.startsWith('http://'))){toast('タイトルと正しいURLを入力してください');return}state.resources.push({id:Date.now(),title,url,category:$('#rCategory').value||'その他',memo:$('#rMemo').value||'メモなし'});localStorage.setItem('matchlab_resources',JSON.stringify(state.resources));closeModal();render();toast('参考動画を追加しました')}if(t.id==='editUser'||t.id==='openSettings')userSettings();if(t.hasAttribute('data-close'))closeModal();if(t.id==='moodOpen')moodModal(state.current);if(t.dataset.confirmReset)resetProgress(Number(t.dataset.confirmReset));if(t.dataset.nextdate)dateInvite(Number(t.dataset.nextdate));if(t.dataset.continuechat){let id=Number(t.dataset.continuechat);closeModal();chat(id)}if(t.dataset.finish){let id=Number(t.dataset.finish);closeModal();state.page='mypage';render();toast(women.find(w=>w.id===id).name+'さんとのデートが確約しました！')}});
$('#openSettings').addEventListener('click',userSettings);
document.addEventListener('click',persistAppState);
document.addEventListener('change',persistAppState);
window.addEventListener('pagehide',persistAppState);
render();
